sheet.css:
.pk{--page:#0d0d0f;--cell:#1a1a1f;--line:#2a2a31;--text:#f5f5f7;--muted:#a1a1aa;--accent:#4ade80;
  --r:18px;--gap:10px;--pad:14px;
  background:var(--page);color:var(--text);font:500 14px/1.5 ui-sans-serif,system-ui,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--page:#0d0d0f;--cell:#1a1a1f;--line:#2a2a31;--text:#f5f5f7;--muted:#a1a1aa}
.stage.pk{--page:#0d0d0f;background:var(--page)}
.stage[data-theme=light]{--page:#f4f4f5}
[data-theme=light].pk,[data-theme=light] .pk{--page:#f4f4f5;--cell:#fff;--line:#d4d4d8;--text:#18181b;--muted:#52525b}

.box{display:grid;grid-template-columns:repeat(4,1fr);grid-auto-rows:74px;gap:var(--gap)}
.b{background:var(--cell);border:1px solid var(--line);border-radius:var(--r);padding:var(--pad);
  display:flex;flex-direction:column;justify-content:flex-end;font-size:12px;color:var(--muted);
  transition:border-color .12s}
.b strong{color:var(--text);font-size:18px;font-weight:600;letter-spacing:-.01em}
.b.hero{grid-column:span 2;grid-row:span 2}
.b.wide{grid-column:span 2}
.b.full{grid-column:span 4}
.b.tall{grid-row:span 2}
.b.act{cursor:pointer}
.b.act:hover{border-color:#3f3f46}
.b .inner{border-radius:4px;overflow:hidden}
.b .up{color:var(--accent);font-weight:600}

.pk-btn{--r2:10px;font:600 13px/1 inherit;background:var(--cell);color:var(--text);
  border:1px solid var(--line);border-radius:var(--r2);padding:9px 14px;cursor:pointer;
  transition:border-color .12s}
.pk-btn:hover{border-color:#52525b}
.pk-btn:focus-visible{outline:2px solid var(--text);outline-offset:2px}
.pk-btn.pri{background:var(--accent);color:#04120a;border-color:var(--accent);font-weight:600}
.pk-btn[disabled]{opacity:.45;cursor:not-allowed;border-color:var(--line)}
.f-hover{border-color:#52525b!important}
.f-focus{outline:2px solid var(--text);outline-offset:2px}

.pk-field{width:100%;background:#101014;color:var(--text);border:1px solid var(--line);
  border-radius:10px;padding:9px 12px;font:500 14px/1.2 inherit}
.pk-field:focus-visible{outline:2px solid var(--text);outline-offset:2px}
.pk-label{display:block;font-size:12px;color:var(--muted);margin-bottom:6px}
.pk-err{margin-top:8px;font-size:12px;color:#fca5a5;display:flex;gap:6px;align-items:center}
.pk-err b{color:#fca5a5}

.pk-nav{display:flex;align-items:center;gap:14px;background:var(--cell);border:1px solid var(--line);
  border-radius:var(--r);padding:10px 14px}
.pk-nav .brand{color:var(--text);font-weight:600}
.pk-nav a{color:var(--muted);text-decoration:none;font-size:13px;padding:5px 9px;border-radius:8px}
.pk-nav a[aria-current]{background:#26262c;color:var(--text)}
.pk-nav .sp{flex:1}

table.pk-t{width:100%;border-collapse:collapse;font-size:13px}
table.pk-t th{text-align:left;color:var(--muted);font-size:11px;letter-spacing:.08em;
  text-transform:uppercase;font-weight:600;padding:0 0 8px}
table.pk-t td{padding:8px 0;border-top:1px solid var(--line);color:var(--text)}

.pk-scrim{background:rgba(0,0,0,.72);border-radius:var(--r);padding:34px 18px;display:flex;justify-content:center}
.pk-dialog{background:var(--cell);border:1px solid var(--line);border-radius:var(--r);padding:18px;max-width:340px;width:100%}
.pk-empty{border:1px dashed var(--line);border-radius:var(--r);padding:22px;text-align:center;color:var(--muted)}
.pk-skel{height:12px;background:#26262c;border-radius:6px;margin-bottom:8px}
.swatch{border:1px solid var(--line,#2a2a31);border-radius:8px;height:54px}
